if(isset($_GET['delete'])) { $id=(int)$_GET['delete']; if($id !== (int)$_SESSION['user']['id']) { $stmt=$conn->prepare("DELETE FROM users WHERE id=? AND role='user'"); $stmt->execute([$id]); } header('Location: users.php'); exit; }
